sp_widget.client_script:
api.controller = function($scope, $window, $location, $rootScope, spUtil) {

    /* widget controller */
    var c = this;


    $rootScope.$on('spModel.gForm.env.created', function(event, toState, toParams) {
        var button = $window.document.getElementById('hazardlinkbutton');

        if (button) {
            button.remove();
        }

        if ($location.search().table == 'x_hccc_hoc_ohs_hazard_investigation_and_risk_assessment' &&
            $location.search().sys_id && $location.search().sys_id != '-1') {

            var panel = $window.document.getElementsByClassName('panel-footer');
            var link = $window.document.createElement('a');
            var linkText = $window.document.createTextNode(c.data.buttonText + " (" + c.data.actionCount + ")");

            link.appendChild(linkText);
            link.classList.add("hira_button", "btn", "btn-primary", "action-btn");
            link.id = 'hazardlinkbutton';
            if (c.data.actionCount > 0) {
                link.href = '?id=hoc_hira_rl_form&table=x_hccc_hoc_ohs_hira_action&parent=' + c.data.hazardId +
                    '&view=sp&parent_field=parent_hazard&sys_id=' + c.data.firstAction;

            } else {
                var parent = $location.search().sys_id;

                link.href = '?id=hoc_hira_rl_form&table=x_hccc_hoc_ohs_hira_action&parent=' + parent +
                    '&view=sp&parent_field=parent_hazard&sys_id=-1&query=parent_hazard=' + parent;
            }

            // just in case the 'form' widget changes in upgrade
            if (panel && panel[0]) {
                panel[0].insertBefore(link, panel[0].firstChild);
            } else {
                var div = $window.document.getElementById('fallback-button-location-hoc');

                div.appendChild(link);
            }
        }
    })

/* //TODO uncomment, add it to the onCreate event above, and make it go to the parent record post delete.
    c.uiAction = function(action) {
        function update() {
            c.server.update().then(function() {
                c.data.action = undefined;
                c.data.result = "completed";
            });
            window.setTimeout(restartscreen, 2000);

            function restartscreen() {
                location.reload(true);
            }
        }

        c.data.action = action;
        if (c.data.action === 'delete') {
            var ans = confirm("Are you sure, you want to delete it?");

            if (ans === true) {
                update();
            } else {
                return false;
            }
        }
    };
	*/

}

sp_widget.script:
(function() {
    /* global data, $sp, options, GlideAggregate, input */
    /* populate the 'data' object */
    /* e.g., data.table = $sp.getValue('table'); */
    function generateButtonAddViewAction() {
        data.buttonText = gs.getMessage("Add/View Actions");
        data.actionCount = 0;
        data.table = $sp.getParameter('table');


        data.hazardId = $sp.getParameter('sys_id');
        data.table = $sp.getParameter('table');
        var actionCount = new GlideAggregate('x_hccc_hoc_ohs_hira_action');

        actionCount.addAggregate('COUNT');
        actionCount.addQuery('parent_hazard', data.hazardId);
        actionCount.query();
        while (actionCount.next()) {
            data.actionCount = actionCount.getAggregate('COUNT');

        }

        var firstAction = new GlideRecordSecure('x_hccc_hoc_ohs_hira_action');

        firstAction.addQuery('parent_hazard', data.hazardId);
        firstAction.setLimit(1);
        firstAction.query();
        if (firstAction.next()) {
            data.firstAction = firstAction.sys_id.toString();
        } else {
            data.firstAction = '-1';
        }
    }

    /** 
     * taken from: https://www.servicenow.com/community/developer-forum/create-delete-action-button-in-service-portal-for-deleting/m-p/1787278
     */
    function generateButtonDelete() {
        var gr = $sp.getRecord();
        var action;
        var states = "";
        var stages = "";
        var ReqCancel = "";
        var b;
        var t;
        var c;

        // Get table & sys_id
        data.table = input.table || $sp.getParameter("table");
        data.sys_id = input.sys_id || $sp.getParameter("sys_id");

        data.canRead = gr.canRead();
        if (!data.canRead) {
            return;
        }

        data.canWrite = gr.canWrite();
        if (!data.canWrite) {
            return;
        }

        b = $sp.getField(gr, 'state');
        if (!gs.nil(b)) {
            states = b.value;
        }

        t = $sp.getField(gr, 'stage');
        if (!gs.nil(t)) {
            stages = t.value;
        }

        c = $sp.getField(gr, 'u_asked_cancellation');
        if (!gs.nil(c)) {
            ReqCancel = c.value;
        }

        // Valid GlideRecord
        gr = new GlideRecord(data.table);
        if (!gr.isValid()) {
            return;
        }

        // Valid sys_id
        if (!gr.get(data.sys_id)) {
            return;
        }

        if (input && input.action) {
            if (input.action === 'delete') {
                gr.deleteRecord();
            }
        }

    }

    generateButtonAddViewAction();
    //generateButtonDelete();
})();
